import { useState, useEffect } from 'react';
import { supabase } from '../config';

export default function ModalLihatLogin({ karyawan, onTutup, onResetPin }) {
  const [loginInfo, setLoginInfo]   = useState(null);
  const [loading, setLoading]       = useState(true);
  const [editMode, setEditMode]     = useState(null); // null | 'pin' | 'username'
  const [pinBaru, setPinBaru]       = useState('');
  const [usernameBaru, setUsernameBaru] = useState('');
  const [saving, setSaving]         = useState(false);
  const [msg, setMsg]               = useState('');

  useEffect(() => {
    async function load() {
      const { data } = await supabase
        .from('users')
        .select('id, username, pin, role, aktif')
        .eq('id', karyawan.id_user)
        .single();
      setLoginInfo(data);
      setLoading(false);
    }
    load();
  }, [karyawan.id_user]);

  async function handleSimpanPin() {
    if (!pinBaru || pinBaru.length < 4) { setMsg('❌ PIN minimal 4 digit!'); return; }
    setSaving(true);
    const { error } = await supabase.from('users').update({ pin: pinBaru }).eq('id', karyawan.id_user);
    setSaving(false);
    if (!error) {
      setLoginInfo(l => ({ ...l, pin: pinBaru }));
      setPinBaru(''); setEditMode(null);
      setMsg('✅ PIN berhasil diubah!');
    } else {
      setMsg('❌ Gagal: ' + error.message);
    }
  }

  async function handleSimpanUsername() {
    if (!usernameBaru || usernameBaru.length < 3) { setMsg('❌ Username minimal 3 karakter!'); return; }
    setSaving(true);
    const { error } = await supabase.from('users').update({ username: usernameBaru.toLowerCase() }).eq('id', karyawan.id_user);
    setSaving(false);
    if (!error) {
      setLoginInfo(l => ({ ...l, username: usernameBaru.toLowerCase() }));
      setUsernameBaru(''); setEditMode(null);
      setMsg('✅ Username berhasil diubah!');
    } else if (error.message.includes('unique')) {
      setMsg('❌ Username sudah dipakai orang lain!');
    } else {
      setMsg('❌ Gagal: ' + error.message);
    }
  }

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onTutup()}>
      <div className="modal-sheet center" style={{ margin: 16, maxWidth: 420 }}>
        <div className="modal-handle" />

        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20 }}>
          <div style={{ width: 48, height: 48, borderRadius: '50%', background: 'var(--green-light)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, fontWeight: 700, color: 'var(--green-dark)', flexShrink: 0 }}>
            {karyawan.nama.split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase()}
          </div>
          <div>
            <div style={{ fontWeight: 700, fontSize: 16 }}>{karyawan.nama}</div>
            <div style={{ fontSize: 12, color: 'var(--gray-500)' }}>{karyawan.nama_toko} · {karyawan.jabatan}</div>
          </div>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: 24, color: 'var(--gray-500)' }}>Memuat...</div>
        ) : loginInfo ? (
          <>
            {/* Info login */}
            <div style={{ background: 'var(--gray-50)', borderRadius: 12, padding: 16, marginBottom: 16 }}>

              {/* Username */}
              <div style={{ marginBottom: 14 }}>
                <div style={{ fontSize: 11, color: 'var(--gray-500)', marginBottom: 6, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Username</div>
                {editMode === 'username' ? (
                  <div style={{ display: 'flex', gap: 8 }}>
                    <input className="form-input" style={{ flex: 1, fontFamily: 'var(--mono)' }}
                      value={usernameBaru}
                      onChange={e => setUsernameBaru(e.target.value.toLowerCase())}
                      placeholder={loginInfo.username}
                      autoCapitalize="none"
                      autoFocus
                    />
                    <button onClick={handleSimpanUsername} disabled={saving}
                      style={{ padding: '8px 14px', background: 'var(--green)', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: 13 }}>
                      {saving ? '...' : 'Simpan'}
                    </button>
                    <button onClick={() => { setEditMode(null); setUsernameBaru(''); }}
                      style={{ padding: '8px 12px', background: 'var(--gray-100)', border: 'none', borderRadius: 8, cursor: 'pointer', fontSize: 13 }}>✕</button>
                  </div>
                ) : (
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <span style={{ fontFamily: 'var(--mono)', fontSize: 18, fontWeight: 700, color: 'var(--gray-900)' }}>
                      {loginInfo.username}
                    </span>
                    <button onClick={() => { setEditMode('username'); setUsernameBaru(loginInfo.username); setMsg(''); }}
                      style={{ fontSize: 11, padding: '5px 12px', background: '#EEF2FF', color: '#4F46E5', border: 'none', borderRadius: 20, cursor: 'pointer', fontWeight: 600 }}>
                      Ubah
                    </button>
                  </div>
                )}
              </div>

              {/* PIN */}
              <div>
                <div style={{ fontSize: 11, color: 'var(--gray-500)', marginBottom: 6, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>PIN</div>
                {editMode === 'pin' ? (
                  <div style={{ display: 'flex', gap: 8 }}>
                    <input className="form-input pin" type="password" inputMode="numeric" maxLength={6}
                      style={{ flex: 1 }} value={pinBaru}
                      onChange={e => setPinBaru(e.target.value)}
                      placeholder="PIN baru" autoFocus
                    />
                    <button onClick={handleSimpanPin} disabled={saving}
                      style={{ padding: '8px 14px', background: 'var(--green)', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: 13 }}>
                      {saving ? '...' : 'Simpan'}
                    </button>
                    <button onClick={() => { setEditMode(null); setPinBaru(''); }}
                      style={{ padding: '8px 12px', background: 'var(--gray-100)', border: 'none', borderRadius: 8, cursor: 'pointer', fontSize: 13 }}>✕</button>
                  </div>
                ) : (
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <span style={{ fontFamily: 'var(--mono)', fontSize: 18, fontWeight: 700, letterSpacing: 6, color: 'var(--gray-900)' }}>
                      {loginInfo.pin}
                    </span>
                    <button onClick={() => { setEditMode('pin'); setPinBaru(''); setMsg(''); }}
                      style={{ fontSize: 11, padding: '5px 12px', background: '#FFF7ED', color: '#C2410C', border: 'none', borderRadius: 20, cursor: 'pointer', fontWeight: 600 }}>
                      Reset PIN
                    </button>
                  </div>
                )}
              </div>
            </div>

            {/* Pesan status */}
            {msg && (
              <div style={{ padding: '10px 14px', borderRadius: 8, marginBottom: 12, fontSize: 13, fontWeight: 500,
                background: msg.startsWith('✅') ? 'var(--green-light)' : 'var(--red-light)',
                color: msg.startsWith('✅') ? 'var(--green-dark)' : 'var(--red)'
              }}>{msg}</div>
            )}

            {/* Info bagikan */}
            <div style={{ background: '#EEF2FF', borderRadius: 10, padding: '10px 14px', marginBottom: 16, fontSize: 11, color: '#4338CA', lineHeight: 1.6 }}>
              📱 <strong>Bagikan ke karyawan:</strong><br/>
              Buka <strong>absensiccgroup-apk.github.io/absensi-app</strong><br/>
              Login dengan username dan PIN di atas
            </div>

            <button className="btn btn-outline" onClick={onTutup}>Tutup</button>
          </>
        ) : (
          <div style={{ textAlign: 'center', padding: 24, color: 'var(--red)' }}>Data login tidak ditemukan</div>
        )}
      </div>
    </div>
  );
}
