import { useState } from 'react';
import { API, Helper } from '../api';
import { showLoading, hideLoading, showToast } from '../components/UI';

export default function Login({ onLogin }) {
  const [username, setUsername] = useState('');
  const [pin, setPin]           = useState('');
  const [error, setError]       = useState('');

  async function handleLogin(e) {
    e?.preventDefault();
    setError('');
    if (!username || !pin) { setError('Username dan PIN wajib diisi'); return; }

    showLoading('Memeriksa akun...');
    const res = await API.login(username, pin);
    hideLoading();

    if (!res.ok) {
      setError(res.error || 'Username atau PIN salah');
      return;
    }

    Helper.simpanSession(res.user);
    onLogin(res.user);
  }

  return (
    <div className="login-page">
      <div className="login-card">
        <div className="login-logo">
          <div className="login-logo-icon">📋</div>
          <div className="login-logo-text">
            <h1>AbsensiApp</h1>
            <p>Sistem Absensi Karyawan</p>
          </div>
        </div>
        <p className="login-subtitle">Masuk dengan username dan PIN Anda</p>

        <div className="form-group">
          <label className="form-label">Username</label>
          <input
            className="form-input"
            type="text"
            placeholder="contoh: budi01"
            value={username}
            onChange={e => setUsername(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleLogin()}
            autoCapitalize="none"
            autoComplete="off"
          />
        </div>

        <div className="form-group">
          <label className="form-label">PIN</label>
          <input
            className="form-input pin"
            type="password"
            placeholder="••••"
            maxLength={6}
            inputMode="numeric"
            value={pin}
            onChange={e => setPin(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleLogin()}
          />
        </div>

        <button className="btn btn-primary" onClick={handleLogin}>
          Masuk →
        </button>

        {error && <div className="error-box">{error}</div>}
      </div>
    </div>
  );
}
