import { useState } from 'react';

const JABATAN_GROUPS = [
  { label: 'Pimpinan', options: ['Owner / Direktur'] },
  { label: 'Manajemen', options: ['Manager', 'Supervisor'] },
  { label: 'Operasional', options: ['Staff', 'Kasir', 'Driver', 'Kurir', 'Admin'] },
];

export default function ModalTambahKaryawan({ toko, onSimpan, onBatal }) {
  const [form, setForm] = useState({
    username: '', pin: '', nama: '',
    id_toko : toko[0]?.id || '',
    tipe    : 'Harian',
    jabatan : 'Staff',
    jabatan_custom: '',
    no_hp   : '',
    tanggal_mulai: '',
    role    : 'karyawan'
  });

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  function handleSimpan() {
    if (!form.username || !form.pin || !form.nama || !form.id_toko) {
      alert('Username, PIN, nama, dan toko wajib diisi!');
      return;
    }
    if (form.pin.length < 4) { alert('PIN minimal 4 digit!'); return; }
    const jabatanFinal = form.jabatan === 'custom' ? form.jabatan_custom : form.jabatan;
    if (!jabatanFinal) { alert('Jabatan wajib diisi!'); return; }
    onSimpan({ ...form, jabatan: jabatanFinal });
  }

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onBatal()}>
      <div className="modal-sheet center" style={{ margin: 16, maxWidth: 560 }}>
        <div className="modal-handle" />
        <div style={{ fontWeight: 700, fontSize: 17, marginBottom: 20 }}>➕ Tambah Karyawan Baru</div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 14 }}>
          <div className="form-group" style={{ margin: 0, gridColumn: '1 / -1' }}>
            <label className="form-label">Nama Lengkap *</label>
            <input className="form-input" value={form.nama}
              onChange={e => set('nama', e.target.value)} placeholder="Budi Santoso" />
          </div>

          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label">Username *</label>
            <input className="form-input" value={form.username}
              onChange={e => set('username', e.target.value.toLowerCase())}
              placeholder="budi01" autoCapitalize="none" />
          </div>

          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label">PIN * (min 4 digit)</label>
            <input className="form-input pin" type="password" inputMode="numeric"
              maxLength={6} value={form.pin}
              onChange={e => set('pin', e.target.value)} placeholder="••••" />
          </div>

          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label">No HP</label>
            <input className="form-input" type="tel" value={form.no_hp}
              onChange={e => set('no_hp', e.target.value)} placeholder="0812..." />
          </div>

          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label">Tanggal Mulai Kerja</label>
            <input className="form-input" type="date" value={form.tanggal_mulai}
              onChange={e => set('tanggal_mulai', e.target.value)} />
          </div>

          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label">Toko *</label>
            <select className="form-input" value={form.id_toko}
              onChange={e => set('id_toko', e.target.value)}>
              {toko.map(t => <option key={t.id} value={t.id}>{t.nama}</option>)}
            </select>
          </div>

          <div className="form-group" style={{ margin: 0 }}>
            <label className="form-label">Tipe Karyawan</label>
            <select className="form-input" value={form.tipe}
              onChange={e => set('tipe', e.target.value)}>
              <option value="Harian">Harian</option>
              <option value="Bulanan">Bulanan</option>
            </select>
          </div>

          <div className="form-group" style={{ margin: 0, gridColumn: '1 / -1' }}>
            <label className="form-label">Jabatan</label>
            <select className="form-input" value={form.jabatan}
              onChange={e => set('jabatan', e.target.value)}
              style={{ marginBottom: form.jabatan === 'custom' ? 8 : 0 }}>
              {JABATAN_GROUPS.map(g => (
                <optgroup key={g.label} label={`── ${g.label} ──`}>
                  {g.options.map(o => <option key={o} value={o}>{o}</option>)}
                </optgroup>
              ))}
              <optgroup label="── Lainnya ──">
                <option value="custom">✏️ Tulis Sendiri...</option>
              </optgroup>
            </select>
            {form.jabatan === 'custom' && (
              <input className="form-input" value={form.jabatan_custom}
                onChange={e => set('jabatan_custom', e.target.value)}
                placeholder="Tulis jabatan..." autoFocus />
            )}
          </div>
        </div>

        <div style={{ background: 'var(--blue-light)', border: '1px solid #BFDBFE', borderRadius: 8, padding: 12, marginBottom: 16, fontSize: 12, color: 'var(--blue)' }}>
          ℹ️ ID User dan ID Karyawan dibuat otomatis. Karyawan bisa langsung login setelah ditambahkan.
        </div>

        <div style={{ display: 'flex', gap: 10 }}>
          <button className="btn btn-outline" style={{ flex: '0.4' }} onClick={onBatal}>Batal</button>
          <button className="btn btn-primary" style={{ flex: 1 }} onClick={handleSimpan}>✅ Tambah Karyawan</button>
        </div>
      </div>
    </div>
  );
}
