import { useState, useEffect } from 'react';
import './index.css';
import { Helper } from './api';
import { Toast, Loading, useToast, useLoading } from './components/UI';
import Login from './pages/Login';
import HalamanAbsen from './pages/HalamanAbsen';
import HalamanManager from './pages/HalamanManager';
import Dashboard from './pages/Dashboard';

export default function App() {
  const [user, setUser] = useState(null);
  const toast   = useToast();
  const loading = useLoading();

  useEffect(() => {
    // Restore session
    const session = Helper.getSession();
    if (session) setUser(session);
  }, []);

  function handleLogin(userData) {
    setUser(userData);
  }

  function handleLogout() {
    if (!window.confirm('Yakin ingin keluar?')) return;
    Helper.hapusSession();
    setUser(null);
  }

  return (
    <>
      <Toast toast={toast} />
      <Loading loading={loading} />

      {!user && <Login onLogin={handleLogin} />}

      {user?.role === 'owner'    && <Dashboard      user={user} onLogout={handleLogout} />}
      {user?.role === 'manager'  && <HalamanManager user={user} onLogout={handleLogout} />}
      {user?.role === 'karyawan' && <HalamanAbsen   user={user} onLogout={handleLogout} />}
    </>
  );
}
