import { useState, useEffect, useCallback } from 'react';

// ============================================
// TOAST HOOK
// ============================================
let toastFn = null;

export function useToast() {
  const [toast, setToast] = useState({ msg: '', type: 'success', show: false });

  useEffect(() => {
    toastFn = (msg, type = 'success') => {
      setToast({ msg, type, show: true });
      setTimeout(() => setToast(t => ({ ...t, show: false })), 3500);
    };
    return () => { toastFn = null; };
  }, []);

  return toast;
}

export function showToast(msg, type = 'success') {
  if (toastFn) toastFn(msg, type);
}

export function Toast({ toast }) {
  return (
    <div className={`toast ${toast.type} ${toast.show ? 'show' : ''}`}>
      {toast.msg}
    </div>
  );
}

// ============================================
// LOADING HOOK
// ============================================
let loadingFn = null;

export function useLoading() {
  const [loading, setLoading] = useState({ show: false, text: '' });

  useEffect(() => {
    loadingFn = (show, text = 'Memproses...') => setLoading({ show, text });
    return () => { loadingFn = null; };
  }, []);

  return loading;
}

export function showLoading(text = 'Memproses...') { if (loadingFn) loadingFn(true, text); }
export function hideLoading() { if (loadingFn) loadingFn(false, ''); }

export function Loading({ loading }) {
  if (!loading.show) return null;
  return (
    <div className="loading-overlay">
      <div className="loading-spinner" />
      <div className="loading-text">{loading.text}</div>
    </div>
  );
}
