import { useState } from 'react';

const OPTIONS_MASUK  = ['Tepat Waktu', 'Terlambat', 'Alasan Lain'];
const OPTIONS_KELUAR = ['Tepat Waktu', 'Pulang Cepat', 'Alasan Lain'];
const OPTIONS_MANAJER= ['Tepat Waktu', 'Terlambat', 'Pulang Cepat', 'Alpha', 'Izin Sakit', 'Izin Keperluan', 'Lainnya'];

export default function ModalKeterangan({ mode, forKaryawan, onSimpan, onBatal }) {
  const [selected, setSelected] = useState('');
  const [menit, setMenit]       = useState('');
  const [ket, setKet]           = useState('');

  const options = forKaryawan
    ? OPTIONS_MANAJER
    : mode === 'masuk' ? OPTIONS_MASUK : OPTIONS_KELUAR;

  const butuhMenit = selected === 'Terlambat' || selected === 'Pulang Cepat';

  function handleSimpan() {
    if (!selected) return;
    let ketFinal = selected;
    if (menit) ketFinal += ` (${menit} menit)`;
    if (ket)   ketFinal += ` — ${ket}`;
    onSimpan(selected, ketFinal);
  }

  const title = forKaryawan
    ? `Keterangan untuk ${forKaryawan}`
    : mode === 'masuk' ? 'Keterangan Absen Masuk' : 'Keterangan Absen Keluar';

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onBatal()}>
      <div className="modal-sheet">
        <div className="modal-handle" />
        <div className="modal-title">{title}</div>

        <div className="radio-group">
          {options.map(opt => (
            <div
              key={opt}
              className={`radio-item ${selected === opt ? 'selected' : ''}`}
              onClick={() => setSelected(opt)}
            >
              <div className="radio-dot" />
              <span style={{ fontSize: 13, fontWeight: 500 }}>{opt}</span>
            </div>
          ))}
        </div>

        {butuhMenit && (
          <div className="form-group">
            <label className="form-label">
              {selected === 'Terlambat' ? 'Terlambat berapa menit?' : 'Lebih awal berapa menit?'}
            </label>
            <input
              className="form-input"
              type="number"
              placeholder="contoh: 30"
              value={menit}
              onChange={e => setMenit(e.target.value)}
              min={1}
            />
          </div>
        )}

        <div className="form-group">
          <label className="form-label">Keterangan tambahan (opsional)</label>
          <textarea
            style={{
              width: '100%', padding: '10px 12px',
              border: '1.5px solid var(--gray-300)', borderRadius: 8,
              fontSize: 13, fontFamily: 'var(--font)',
              resize: 'none', height: 80, outline: 'none'
            }}
            placeholder="Tulis keterangan di sini..."
            value={ket}
            onChange={e => setKet(e.target.value)}
          />
        </div>

        <div style={{ display: 'flex', gap: 8 }}>
          <button className="btn btn-outline" style={{ flex: '0.4' }} onClick={onBatal}>
            Batal
          </button>
          <button
            className="btn btn-primary"
            style={{ flex: 1 }}
            onClick={handleSimpan}
            disabled={!selected}
          >
            Simpan Keterangan
          </button>
        </div>
      </div>
    </div>
  );
}
