import { useState, useEffect } from 'react';
import { API, GPS, Helper } from '../api';
import { showLoading, hideLoading, showToast } from '../components/UI';
import Kamera from '../components/Kamera';
import ModalKeterangan from '../components/ModalKeterangan';

export default function HalamanAbsen({ user, onLogout }) {
  const [toko, setToko]         = useState(null);
  const [absen, setAbsen]       = useState(null);
  const [gps, setGps]           = useState({ status: 'loading', jarak: 0, lat: 0, lon: 0 });
  const [kameraMode, setKamera] = useState(null); // null | 'masuk' | 'keluar'
  const [fotoBlob, setFotoBlob] = useState(null);
  const [showKet, setShowKet]   = useState(false);

  const jam  = new Date().getHours();
  const sapaan = jam < 12 ? 'Selamat pagi' : jam < 15 ? 'Selamat siang' : jam < 18 ? 'Selamat sore' : 'Selamat malam';

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    showLoading('Memuat data...');
    try {
      // Ambil data toko
      if (user.id_toko !== 'semua') {
        const { supabase } = await import('../config');
        const { data } = await supabase.from('toko').select('*').eq('id', user.id_toko).single();
        if (data) setToko(data);
      }

      // Cek absen hari ini
      const res = await API.cekAbsen(user.id_user);
      if (res.ok) setAbsen(res);
    } catch (e) {
      console.error(e);
    }
    hideLoading();

    // Cek GPS
    cekGPS();
  }

  async function cekGPS() {
    setGps({ status: 'loading', jarak: 0, lat: 0, lon: 0 });
    try {
      const lok = await GPS.getLokasi();
      if (!toko?.lat) {
        setGps({ status: 'ok', jarak: 0, ...lok });
        return;
      }
      const jarak = GPS.hitungJarak(lok.lat, lok.lon, toko.lat, toko.lon);
      const valid = jarak <= (toko.radius || 50);
      setGps({ status: valid ? 'ok' : 'err', jarak, ...lok });
    } catch (e) {
      setGps({ status: 'err', jarak: 0, lat: 0, lon: 0 });
    }
  }

  function mulaiAbsen(mode) {
    if (gps.status === 'err' && toko?.lat) {
      showToast('Anda berada di luar area kantor!', 'error');
      return;
    }
    setKamera(mode);
  }

  function handleFoto(blob) {
    setFotoBlob(blob);
    setKamera(null);
    setShowKet(true);
  }

  async function handleKeterangan(status, ketFinal) {
    setShowKet(false);
    await prosesAbsen(status, ketFinal);
  }

  async function prosesAbsen(status, keterangan) {
    showLoading(kameraMode === 'masuk' || !absen?.sudah_masuk
      ? 'Menyimpan absen masuk...' : 'Menyimpan absen keluar...');

    try {
      const jam_now  = Helper.jamSekarang();
      const idLog    = Helper.generateId('L');
      const namaFolder = `${user.id_toko}_${user.nama_toko}`;
      const namaFile = `${user.id_user}_${jam_now.replace(':','')}.jpg`;

      // Upload foto ke Google Drive
      let fotoUrl = '';
      if (fotoBlob) {
        showLoading('Mengupload foto...');
        const up = await API.uploadFoto(fotoBlob, namaFile, namaFolder);
        if (up.ok) fotoUrl = up.url;
      }

      const isAbsenMasuk = !absen?.sudah_masuk;

      if (isAbsenMasuk) {
        let statusMasuk = 'Tepat Waktu';
        if (toko?.jam_masuk) {
          const s = Helper.statusMasuk(toko.jam_masuk, toko.toleransi || 15);
          statusMasuk = status || s.status;
        }

        const res = await API.absenMasuk({
          id_log      : idLog,
          id_user     : user.id_user,
          id_karyawan : user.id_karyawan || '',
          id_toko     : user.id_toko,
          nama_toko   : user.nama_toko,
          nama        : user.nama,
          jam_masuk   : jam_now,
          lat         : gps.lat,
          lon         : gps.lon,
          jarak       : gps.jarak,
          foto        : fotoUrl,
          status_masuk: statusMasuk,
          keterangan  : keterangan || ''
        });

        if (res?.ok) {
          setAbsen({ sudah_masuk: true, sudah_keluar: false, jam_masuk: jam_now, id_log: idLog });
          showToast(`Absen masuk berhasil — ${jam_now}`, 'success');
        }
      } else {
        let statusKeluar = 'Tepat Waktu';
        if (toko?.jam_keluar) {
          const s = Helper.statusKeluar(toko.jam_keluar);
          statusKeluar = status || s.status;
        }

        const res = await API.absenKeluar({
          id_log       : absen.id_log,
          nama         : user.nama,
          nama_toko    : user.nama_toko,
          jam_keluar   : jam_now,
          lat          : gps.lat,
          lon          : gps.lon,
          jarak        : gps.jarak,
          foto         : fotoUrl,
          status_keluar: statusKeluar,
          keterangan   : keterangan || ''
        });

        if (res?.ok) {
          setAbsen(a => ({ ...a, sudah_keluar: true, jam_keluar: jam_now }));
          showToast(`Absen keluar berhasil — ${jam_now}`, 'success');
        }
      }
    } catch (e) {
      showToast('Error: ' + e.message, 'error');
    }

    hideLoading();
    setFotoBlob(null);
  }

  const sudahMasuk  = absen?.sudah_masuk;
  const sudahKeluar = absen?.sudah_keluar;
  const absenMode   = !sudahMasuk ? 'masuk' : !sudahKeluar ? 'keluar' : null;

  // Tampilkan kamera
  if (kameraMode) return (
    <Kamera
      mode={kameraMode}
      onFoto={handleFoto}
      onBatal={() => setKamera(null)}
    />
  );

  return (
    <div style={{ background: 'var(--gray-50)', minHeight: '100vh' }}>
      {/* Header */}
      <div className="absen-header">
        <div className="absen-header-top">
          <span className="absen-app-name">AbsensiApp</span>
          <button className="btn-logout-sm" onClick={onLogout}>Keluar</button>
        </div>
        <div className="greeting">{sapaan}, {user.nama}!</div>
        <div className="greeting-sub">{user.nama_toko}</div>
      </div>

      <div className="absen-body">
        {/* Status absen */}
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
            <div style={{ fontSize: 11, color: 'var(--gray-500)' }}>
              {Helper.tanggalHariIni()}
            </div>
            <div className={`badge ${!sudahMasuk ? 'badge-belum' : !sudahKeluar ? 'badge-hadir' : 'badge-hadir'}`}>
              {!sudahMasuk ? 'Belum Absen' : !sudahKeluar ? 'Sudah Masuk' : 'Selesai ✓'}
            </div>
          </div>
          <div className="time-grid">
            <div className="time-box">
              <div className="time-label">Jam Masuk</div>
              <div className="time-val" style={{ color: sudahMasuk ? 'var(--green)' : 'var(--gray-300)' }}>
                {absen?.jam_masuk || '--:--'}
              </div>
            </div>
            <div className="time-box">
              <div className="time-label">Jam Keluar</div>
              <div className="time-val" style={{ color: sudahKeluar ? 'var(--green)' : 'var(--gray-300)' }}>
                {absen?.jam_keluar || '--:--'}
              </div>
            </div>
          </div>
        </div>

        {/* Aturan toko */}
        {toko && (
          <div className="card" style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
            <div><div style={{ fontSize: 10, color: 'var(--gray-500)' }}>Jam Masuk</div>
              <div style={{ fontSize: 13, fontWeight: 600 }}>{toko.jam_masuk}</div></div>
            <div><div style={{ fontSize: 10, color: 'var(--gray-500)' }}>Toleransi</div>
              <div style={{ fontSize: 13, fontWeight: 600 }}>{toko.toleransi} menit</div></div>
            <div><div style={{ fontSize: 10, color: 'var(--gray-500)' }}>Jam Keluar</div>
              <div style={{ fontSize: 13, fontWeight: 600 }}>{toko.jam_keluar}</div></div>
            <div><div style={{ fontSize: 10, color: 'var(--gray-500)' }}>Hari Kerja</div>
              <div style={{ fontSize: 13, fontWeight: 600 }}>{toko.hari_kerja}</div></div>
          </div>
        )}

        {/* GPS */}
        <div className="card gps-section">
          <div className="gps-card">
            <div className={`gps-dot ${gps.status}`} />
            <div>
              <div className="gps-text">
                {gps.status === 'loading' && 'Mengambil lokasi GPS...'}
                {gps.status === 'ok'      && (toko?.lat ? `Dalam area kantor ✓` : 'GPS aktif')}
                {gps.status === 'err'     && (toko?.lat ? 'Di luar area kantor' : 'GPS tidak dapat diambil')}
              </div>
              <div className="gps-sub">
                {gps.status === 'ok' && toko?.lat && `Jarak ${gps.jarak}m dari titik kantor`}
                {gps.status === 'err' && toko?.lat && `Jarak ${gps.jarak}m — maksimal ${toko.radius}m`}
              </div>
            </div>
            <button
              onClick={cekGPS}
              style={{ marginLeft: 'auto', background: 'none', border: '1px solid var(--gray-300)', borderRadius: 6, padding: '4px 10px', fontSize: 11, cursor: 'pointer' }}
            >
              🔄
            </button>
          </div>
        </div>

        {/* Tombol absen */}
        {absenMode === 'masuk' && (
          <button
            className="btn btn-primary"
            style={{ padding: 14, fontSize: 15 }}
            onClick={() => mulaiAbsen('masuk')}
            disabled={gps.status === 'loading'}
          >
            📸 Absen Masuk
          </button>
        )}

        {absenMode === 'keluar' && (
          <button
            className="btn btn-danger"
            style={{ padding: 14, fontSize: 15 }}
            onClick={() => mulaiAbsen('keluar')}
            disabled={gps.status === 'loading'}
          >
            📸 Absen Keluar
          </button>
        )}

        {!absenMode && (
          <div style={{ textAlign: 'center', padding: '16px', color: 'var(--gray-500)', fontSize: 13 }}>
            ✅ Absensi hari ini sudah selesai
          </div>
        )}
      </div>

      {/* Modal keterangan */}
      {showKet && (
        <ModalKeterangan
          mode={!sudahMasuk ? 'masuk' : 'keluar'}
          onSimpan={handleKeterangan}
          onBatal={() => setShowKet(false)}
        />
      )}
    </div>
  );
}
