import { useState, useRef, useEffect, useCallback } from 'react';

export default function Kamera({ mode, onFoto, onBatal }) {
  const videoRef    = useRef(null);
  const canvasRef   = useRef(null);
  const streamRef   = useRef(null);
  const intervalRef = useRef(null);

  const [fase, setFase]         = useState('live'); // 'live' | 'preview'
  const [fotoBlob, setFotoBlob] = useState(null);
  const [fotoUrl, setFotoUrl]   = useState(null);
  const [wajahOk, setWajahOk]   = useState(false);
  const [wajahMsg, setWajahMsg] = useState('Arahkan wajah ke kamera...');
  const [faceApi, setFaceApi]   = useState(null);

  // Load face-api.js dari CDN
  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/face-api.js@0.22.2/dist/face-api.min.js';
    script.onload = async () => {
      try {
        await Promise.all([
          window.faceapi.nets.tinyFaceDetector.loadFromUri(
            'https://cdn.jsdelivr.net/npm/face-api.js@0.22.2/weights'
          )
        ]);
        setFaceApi(window.faceapi);
      } catch (e) {
        // Jika gagal load model, izinkan tanpa deteksi wajah
        setWajahOk(true);
        setWajahMsg('Siap foto');
      }
    };
    script.onerror = () => {
      setWajahOk(true);
      setWajahMsg('Siap foto');
    };
    document.head.appendChild(script);

    bukaKamera();
    return () => {
      tutupKamera();
      if (intervalRef.current) clearInterval(intervalRef.current);
      document.head.removeChild(script);
    };
  }, []);

  // Deteksi wajah setiap 800ms
  useEffect(() => {
    if (!faceApi || fase !== 'live') return;
    intervalRef.current = setInterval(async () => {
      if (!videoRef.current) return;
      try {
        const deteksi = await faceApi.detectSingleFace(
          videoRef.current,
          new faceApi.TinyFaceDetectorOptions()
        );
        if (deteksi) {
          setWajahOk(true);
          setWajahMsg('✅ Wajah terdeteksi — siap foto!');
        } else {
          setWajahOk(false);
          setWajahMsg('Arahkan wajah ke area oval...');
        }
      } catch { }
    }, 800);

    return () => clearInterval(intervalRef.current);
  }, [faceApi, fase]);

  async function bukaKamera() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } },
        audio: false
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
      }
    } catch (e) {
      setWajahMsg('❌ Kamera tidak bisa diakses');
    }
  }

  function tutupKamera() {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
  }

  async function ambilFoto() {
    if (!videoRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx    = canvas.getContext('2d');
    canvas.width  = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    canvas.toBlob(blob => {
      if (!blob) return;
      setFotoBlob(blob);
      setFotoUrl(URL.createObjectURL(blob));
      setFase('preview');
      tutupKamera();
      if (intervalRef.current) clearInterval(intervalRef.current);
    }, 'image/jpeg', 0.75);
  }

  function ulangFoto() {
    setFotoBlob(null);
    setFotoUrl(null);
    setFase('live');
    setWajahOk(false);
    setWajahMsg('Arahkan wajah ke kamera...');
    bukaKamera();
  }

  function konfirmasi() {
    if (fotoBlob) onFoto(fotoBlob);
  }

  const title = mode === 'masuk' ? 'Foto Absen Masuk' : 'Foto Absen Keluar';

  return (
    <div className="kamera-page">
      <div className="kamera-header">
        <h2>{title}</h2>
        <p>{fase === 'live' ? 'Posisikan wajah di dalam oval' : 'Apakah foto sudah jelas?'}</p>
      </div>

      {/* Video live */}
      {fase === 'live' && (
        <>
          <video ref={videoRef} className="kamera-preview" autoPlay playsInline muted />
          <div className={`face-overlay ${wajahOk ? 'detected' : ''}`} />
          <div className="face-status">{wajahMsg}</div>
        </>
      )}

      {/* Preview foto */}
      {fase === 'preview' && fotoUrl && (
        <img
          src={fotoUrl} alt="Preview"
          className="kamera-preview"
          style={{ transform: 'scaleX(-1)' }}
        />
      )}

      <canvas ref={canvasRef} style={{ display: 'none' }} />

      {/* Controls live */}
      {fase === 'live' && (
        <div className="kamera-footer">
          <button className="btn-kamera-sm" onClick={onBatal}>Batal</button>
          <button
            className="btn-shutter"
            onClick={ambilFoto}
            disabled={!wajahOk}
          >
            <div className="btn-shutter-inner" />
          </button>
          <div style={{ width: 80 }} />
        </div>
      )}

      {/* Controls preview */}
      {fase === 'preview' && (
        <div className="kamera-footer">
          <button className="btn-kamera-sm" onClick={ulangFoto}>Ulangi</button>
          <button className="btn-kamera-ok" onClick={konfirmasi}>Gunakan Foto ✓</button>
        </div>
      )}
    </div>
  );
}
