import { useState, useEffect } from 'react';
import { API, GPS, Helper } from '../api';
import { supabase } from '../config';
import { showLoading, hideLoading, showToast } from '../components/UI';
import Kamera from '../components/Kamera';
import ModalKeterangan from '../components/ModalKeterangan';

export default function HalamanManager({ user, onLogout }) {
  const [toko, setToko]         = useState(null);
  const [absen, setAbsen]       = useState(null);
  const [gps, setGps]           = useState({ status: 'loading', jarak: 0, lat: 0, lon: 0 });
  const [karyawan, setKaryawan] = useState([]);
  const [logHariIni, setLog]    = useState([]);
  const [filter, setFilter]     = useState('semua');
  const [kamera, setKamera]     = useState(null);
  const [fotoBlob, setFotoBlob] = useState(null);
  const [modalKet, setModalKet] = useState(null); // null | { target: 'diri' | {id_log, nama} }
  const [stats, setStats]       = useState({ hadir: 0, telat: 0, alpha: 0, izin: 0 });

  const jam     = new Date().getHours();
  const sapaan  = jam < 12 ? 'Selamat pagi' : jam < 15 ? 'Selamat siang' : 'Selamat sore';

  useEffect(() => { loadData(); }, []);

  async function loadData() {
    showLoading('Memuat data...');
    try {
      // Toko
      const { data: tokoData } = await supabase
        .from('toko').select('*').eq('id', user.id_toko).single();
      if (tokoData) setToko(tokoData);

      // Absen manager sendiri
      const resAbsen = await API.cekAbsen(user.id_user);
      if (resAbsen.ok) setAbsen(resAbsen);

      // Data karyawan + log
      await loadKaryawan();
    } catch (e) { console.error(e); }
    hideLoading();
    cekGPS();
  }

  async function loadKaryawan() {
    const { data: karList } = await supabase
      .from('karyawan')
      .select('*')
      .eq('id_toko', user.id_toko)
      .eq('aktif', true);

    const resDash = await API.getDashboardData(user.id_toko);
    const logList = resDash.ok ? resDash.log : [];
    setLog(logList);

    // Gabungkan karyawan + log
    const merged = (karList || [])
      .filter(k => k.jabatan !== 'Manager')
      .map(k => {
        const log = logList.find(l => l.id_user === k.id_user);
        return {
          ...k,
          jam_masuk   : log?.jam_masuk || '',
          jam_keluar  : log?.jam_keluar || '',
          status_masuk: log?.status_masuk || 'Alpha',
          ket_masuk   : log?.ket_masuk || '',
          id_log      : log?.id_log || null,
        };
      });

    setKaryawan(merged);
    hitungStats(merged);
  }

  function hitungStats(list) {
    setStats({
      hadir: list.filter(k => k.jam_masuk).length,
      telat: list.filter(k => k.status_masuk === 'Terlambat').length,
      alpha: list.filter(k => !k.jam_masuk).length,
      izin : list.filter(k => k.ket_masuk?.toLowerCase().includes('izin')).length,
    });
  }

  async function cekGPS() {
    setGps({ status: 'loading', jarak: 0, lat: 0, lon: 0 });
    try {
      const lok = await GPS.getLokasi();
      if (!toko?.lat) { setGps({ status: 'ok', jarak: 0, ...lok }); return; }
      const jarak = GPS.hitungJarak(lok.lat, lok.lon, toko.lat, toko.lon);
      setGps({ status: jarak <= (toko.radius || 50) ? 'ok' : 'err', jarak, ...lok });
    } catch { setGps({ status: 'err', jarak: 0, lat: 0, lon: 0 }); }
  }

  function mulaiAbsen(mode) {
    if (gps.status === 'err' && toko?.lat) { showToast('Di luar area kantor!', 'error'); return; }
    setKamera(mode);
  }

  function handleFoto(blob) {
    setFotoBlob(blob);
    setKamera(null);
    setModalKet({ target: 'diri' });
  }

  async function handleKeterangan(status, ketFinal) {
    const target = modalKet?.target;
    setModalKet(null);

    if (target === 'diri') {
      await prosesAbsenManager(status, ketFinal);
    } else if (target?.id_log) {
      await updateKetKaryawan(target.id_log, ketFinal);
    }
  }

  async function prosesAbsenManager(status, keterangan) {
    showLoading('Menyimpan absen...');
    try {
      const jam_now    = Helper.jamSekarang();
      const isAbsenMasuk = !absen?.sudah_masuk;
      const namaFolder = `${user.id_toko}_${user.nama_toko}`;
      const namaFile   = `${user.id_user}_${jam_now.replace(':','')}.jpg`;

      let fotoUrl = '';
      if (fotoBlob) {
        showLoading('Mengupload foto...');
        const up = await API.uploadFoto(fotoBlob, namaFile, namaFolder);
        if (up.ok) fotoUrl = up.url;
      }

      if (isAbsenMasuk) {
        const idLog = Helper.generateId('L');
        const s     = toko ? Helper.statusMasuk(toko.jam_masuk, toko.toleransi) : { status: 'Tepat Waktu' };
        await API.absenMasuk({
          id_log: idLog, id_user: user.id_user, id_karyawan: user.id_karyawan,
          id_toko: user.id_toko, nama_toko: user.nama_toko, nama: user.nama,
          jam_masuk: jam_now, lat: gps.lat, lon: gps.lon, jarak: gps.jarak,
          foto: fotoUrl, status_masuk: status || s.status, keterangan
        });
        setAbsen({ sudah_masuk: true, sudah_keluar: false, jam_masuk: jam_now, id_log: idLog });
        showToast(`Absen masuk — ${jam_now}`, 'success');
      } else {
        const s = toko ? Helper.statusKeluar(toko.jam_keluar) : { status: 'Tepat Waktu' };
        await API.absenKeluar({
          id_log: absen.id_log, nama: user.nama, nama_toko: user.nama_toko,
          jam_keluar: jam_now, lat: gps.lat, lon: gps.lon, jarak: gps.jarak,
          foto: fotoUrl, status_keluar: status || s.status, keterangan
        });
        setAbsen(a => ({ ...a, sudah_keluar: true, jam_keluar: jam_now }));
        showToast(`Absen keluar — ${jam_now}`, 'success');
      }
    } catch (e) { showToast('Error: ' + e.message, 'error'); }
    setFotoBlob(null);
    hideLoading();
    await loadKaryawan();
  }

  async function updateKetKaryawan(id_log, keterangan) {
    showLoading('Menyimpan keterangan...');
    const res = await API.updateKeterangan(id_log, keterangan, '', user.nama);
    hideLoading();
    if (res?.ok) {
      showToast('Keterangan tersimpan', 'success');
      await loadKaryawan();
    } else {
      showToast('Gagal simpan', 'error');
    }
  }

  const filtered = filter === 'semua' ? karyawan
    : karyawan.filter(k =>
        filter === 'Hadir' ? !!k.jam_masuk
        : k.status_masuk === filter
      );

  const sudahMasuk  = absen?.sudah_masuk;
  const sudahKeluar = absen?.sudah_keluar;

  if (kamera) return (
    <Kamera mode={kamera} onFoto={handleFoto} onBatal={() => setKamera(null)} />
  );

  return (
    <div style={{ background: 'var(--gray-50)', minHeight: '100vh' }}>
      <div className="manager-header">
        <div className="absen-header-top">
          <span className="absen-app-name">AbsensiApp — Manager</span>
          <button className="btn-logout-sm" onClick={onLogout}>Keluar</button>
        </div>
        <div className="greeting">{sapaan}, {user.nama}!</div>
        <div className="greeting-sub">{user.nama_toko}</div>
        <div className="stat-strip">
          {[['Hadir', stats.hadir], ['Telat', stats.telat], ['Alpha', stats.alpha], ['Izin', stats.izin]].map(([l, v]) => (
            <div key={l} className="stat-strip-item">
              <div className="stat-strip-num">{v}</div>
              <div className="stat-strip-lbl">{l}</div>
            </div>
          ))}
        </div>
      </div>

      <div className="manager-body">
        {/* Absen manager sendiri */}
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
            <div style={{ fontSize: 12, fontWeight: 600 }}>Absensi Saya</div>
            <div className={`badge ${!sudahMasuk ? 'badge-belum' : !sudahKeluar ? 'badge-hadir' : 'badge-hadir'}`}>
              {!sudahMasuk ? 'Belum Absen' : !sudahKeluar ? 'Sudah Masuk' : 'Selesai ✓'}
            </div>
          </div>
          <div className="time-grid" style={{ marginBottom: 10 }}>
            <div className="time-box">
              <div className="time-label">Masuk</div>
              <div className="time-val" style={{ color: sudahMasuk ? 'var(--green)' : 'var(--gray-300)' }}>
                {absen?.jam_masuk || '--:--'}
              </div>
            </div>
            <div className="time-box">
              <div className="time-label">Keluar</div>
              <div className="time-val" style={{ color: sudahKeluar ? 'var(--green)' : 'var(--gray-300)' }}>
                {absen?.jam_keluar || '--:--'}
              </div>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              className="btn btn-primary"
              style={{ flex: 1, fontSize: 13, padding: 10 }}
              disabled={sudahMasuk || gps.status === 'loading'}
              onClick={() => mulaiAbsen('masuk')}
            >📸 Masuk</button>
            <button
              className="btn btn-danger"
              style={{ flex: 1, fontSize: 13, padding: 10 }}
              disabled={!sudahMasuk || sudahKeluar || gps.status === 'loading'}
              onClick={() => mulaiAbsen('keluar')}
            >📸 Keluar</button>
          </div>
        </div>

        {/* GPS */}
        <div className="card gps-section">
          <div className="gps-card">
            <div className={`gps-dot ${gps.status}`} />
            <div>
              <div className="gps-text">
                {gps.status === 'loading' && 'Mengambil GPS...'}
                {gps.status === 'ok'      && (toko?.lat ? `Dalam area kantor ✓` : 'GPS aktif')}
                {gps.status === 'err'     && 'Di luar area kantor'}
              </div>
              {toko?.lat && gps.status !== 'loading' && (
                <div className="gps-sub">Jarak {gps.jarak}m dari kantor</div>
              )}
            </div>
            <button onClick={cekGPS} style={{ marginLeft: 'auto', background: 'none', border: '1px solid var(--gray-300)', borderRadius: 6, padding: '4px 10px', fontSize: 11, cursor: 'pointer' }}>🔄</button>
          </div>
        </div>

        {/* Tanggal */}
        <div style={{ fontSize: 12, color: 'var(--gray-500)', marginBottom: 8 }}>
          {Helper.tanggalHariIni()}
        </div>

        {/* Filter */}
        <div className="filter-tabs">
          {['semua', 'Hadir', 'Terlambat', 'Alpha'].map(f => (
            <button key={f} className={`tab-btn ${filter === f ? 'active' : ''}`}
              onClick={() => setFilter(f)}>
              {f === 'semua' ? 'Semua' : f}
            </button>
          ))}
        </div>

        {/* List karyawan */}
        <div>
          {filtered.length === 0 && (
            <div style={{ textAlign: 'center', padding: 24, color: 'var(--gray-500)', fontSize: 13 }}>
              Tidak ada data
            </div>
          )}
          {filtered.map(k => {
            const inisial = k.nama.split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
            const jamInfo = k.jam_masuk
              ? `Masuk ${k.jam_masuk}${k.jam_keluar ? ' · Keluar ' + k.jam_keluar : ''}`
              : 'Belum absen';
            const badgeClass = k.jam_masuk
              ? (k.status_masuk === 'Terlambat' ? 'badge-telat' : 'badge-hadir')
              : 'badge-alpha';

            return (
              <div key={k.id} className="karyawan-item">
                <div className="karyawan-avatar">{inisial}</div>
                <div className="karyawan-info">
                  <div className="karyawan-nama">{k.nama}</div>
                  <div className="karyawan-detail">{k.tipe} · {jamInfo}</div>
                  {k.ket_masuk && (
                    <div style={{ fontSize: 10, color: 'var(--gray-500)', marginTop: 2 }}>
                      📝 {k.ket_masuk}
                    </div>
                  )}
                  {k.id_log && (
                    <button
                      className="btn-ket"
                      onClick={() => setModalKet({ target: { id_log: k.id_log, nama: k.nama } })}
                    >
                      ✏️ Tambah / Edit Keterangan
                    </button>
                  )}
                </div>
                <div><div className={`badge ${badgeClass}`}>{k.status_masuk}</div></div>
              </div>
            );
          })}
        </div>
      </div>

      {modalKet && (
        <ModalKeterangan
          mode="masuk"
          forKaryawan={modalKet.target?.nama}
          onSimpan={handleKeterangan}
          onBatal={() => setModalKet(null)}
        />
      )}
    </div>
  );
}
