// ============================================
// API UTILITY — Semua panggilan ke Supabase RPC
// ============================================

import { supabase, TELEGRAM, DRIVE_SCRIPT_URL } from './config';

// ============================================
// AUTH
// ============================================
export const API = {

  async login(username, pin) {
    const { data, error } = await supabase.rpc('login_user', {
      p_username: username.trim().toLowerCase(),
      p_pin     : pin.trim()
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  // ============================================
  // ABSENSI
  // ============================================
  async cekAbsen(id_user) {
    const { data, error } = await supabase.rpc('cek_absen_hari_ini', {
      p_id_user: id_user
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  async absenMasuk(params) {
    const { data, error } = await supabase.rpc('absen_masuk', {
      p_id_log     : params.id_log,
      p_id_user    : params.id_user,
      p_id_karyawan: params.id_karyawan || '',
      p_id_toko    : params.id_toko,
      p_jam_masuk  : params.jam_masuk,
      p_lat        : params.lat || 0,
      p_lon        : params.lon || 0,
      p_jarak      : params.jarak || 0,
      p_foto       : params.foto || '',
      p_status     : params.status_masuk || 'Tepat Waktu',
      p_keterangan : params.keterangan || ''
    });
    if (error) return { ok: false, error: error.message };

    // Kirim notifikasi Telegram
    await Telegram.notifMasuk(params);
    return data;
  },

  async absenKeluar(params) {
    const { data, error } = await supabase.rpc('absen_keluar', {
      p_id_log    : params.id_log,
      p_jam_keluar: params.jam_keluar,
      p_lat       : params.lat || 0,
      p_lon       : params.lon || 0,
      p_jarak     : params.jarak || 0,
      p_foto      : params.foto || '',
      p_status    : params.status_keluar || 'Tepat Waktu',
      p_keterangan: params.keterangan || ''
    });
    if (error) return { ok: false, error: error.message };

    await Telegram.notifKeluar(params);
    return data;
  },

  // ============================================
  // DASHBOARD
  // ============================================
  async getDashboardData(id_toko = 'semua') {
    const { data, error } = await supabase.rpc('get_dashboard_data', {
      p_id_toko: id_toko
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  async getRekapHarian(tanggal, id_toko = 'semua') {
    const { data, error } = await supabase.rpc('get_rekap_harian', {
      p_tanggal: tanggal,
      p_id_toko: id_toko
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  async getRekapBulanan(bulan, tahun, id_toko = 'semua') {
    const { data, error } = await supabase.rpc('get_rekap_bulanan', {
      p_bulan  : bulan,
      p_tahun  : tahun,
      p_id_toko: id_toko
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  async updateKeterangan(id_log, ket_masuk, ket_keluar, dicatat_oleh) {
    const { data, error } = await supabase.rpc('update_keterangan', {
      p_id_log      : id_log,
      p_ket_masuk   : ket_masuk || '',
      p_ket_keluar  : ket_keluar || '',
      p_dicatat_oleh: dicatat_oleh
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  async updateToko(params) {
    const { data, error } = await supabase.rpc('update_toko', {
      p_id        : params.id,
      p_nama      : params.nama,
      p_alamat    : params.alamat || '',
      p_lat       : params.lat,
      p_lon       : params.lon,
      p_radius    : params.radius,
      p_jam_masuk : params.jam_masuk,
      p_toleransi : params.toleransi,
      p_jam_keluar: params.jam_keluar,
      p_hari_kerja: params.hari_kerja || ''
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  async tambahKaryawan(params) {
    // Generate ID user berurutan
    const { data: users } = await supabase
      .from('users').select('id').order('id', { ascending: false }).limit(1);
    const lastNum = users?.[0]?.id ? parseInt(users[0].id.substring(1)) : 0;
    const id_user = 'U' + String(lastNum + 1).padStart(3, '0');

    const { data, error } = await supabase.rpc('tambah_karyawan', {
      p_id_user  : id_user,
      p_username : params.username,
      p_pin      : params.pin,
      p_nama     : params.nama,
      p_id_toko  : params.id_toko,
      p_tipe     : params.tipe,
      p_jabatan  : params.jabatan || 'Staff',
      p_no_hp    : params.no_hp || ''
    });
    if (error) return { ok: false, error: error.message };
    return data;
  },

  // ============================================
  // UPLOAD FOTO KE GOOGLE DRIVE
  // ============================================
  async uploadFoto(blob, namaFile, namaFolder) {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = async () => {
        try {
          const base64 = reader.result.split(',')[1];
          const res = await fetch(DRIVE_SCRIPT_URL, {
            method: 'POST',
            body  : JSON.stringify({ action: 'uploadFoto', base64, namaFile, namaFolder })
          });
          const result = await res.json();
          resolve(result);
        } catch (e) {
          resolve({ ok: false, error: e.message });
        }
      };
      reader.readAsDataURL(blob);
    });
  }
};

// ============================================
// TELEGRAM
// ============================================
export const Telegram = {
  async kirim(chatId, pesan) {
    try {
      await fetch(`https://api.telegram.org/bot${TELEGRAM.TOKEN}/sendMessage`, {
        method : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body   : JSON.stringify({ chat_id: chatId, text: pesan, parse_mode: 'HTML' })
      });
    } catch (e) { console.error('Telegram error:', e); }
  },

  async broadcast(pesan) {
    await Promise.all([
      this.kirim(TELEGRAM.GROUP_ID, pesan),
      this.kirim(TELEGRAM.OWNER_ID, pesan)
    ]);
  },

  async notifMasuk(d) {
    const emoji = d.status_masuk === 'Terlambat' ? '⚠️' : '✅';
    let p = `${emoji} <b>ABSEN MASUK — ${d.nama_toko}</b>\n`;
    p    += `👤 ${d.nama}\n🕐 ${d.jam_masuk} WIB\n`;
    p    += `📍 Jarak: ${d.jarak || 0}m\n📊 Status: ${d.status_masuk || 'Tepat Waktu'}`;
    if (d.keterangan) p += `\n📝 ${d.keterangan}`;
    if (d.foto)       p += `\n📸 <a href="${d.foto}">Lihat Foto</a>`;
    await this.broadcast(p);
  },

  async notifKeluar(d) {
    const emoji = d.status_keluar === 'Pulang Cepat' ? '🔔' : '✅';
    let p = `${emoji} <b>ABSEN KELUAR — ${d.nama_toko}</b>\n`;
    p    += `👤 ${d.nama}\n🕐 ${d.jam_keluar} WIB\n`;
    p    += `📊 Status: ${d.status_keluar || 'Tepat Waktu'}`;
    if (d.keterangan) p += `\n📝 ${d.keterangan}`;
    await this.broadcast(p);
  }
};

// ============================================
// GPS
// ============================================
export const GPS = {
  hitungJarak(lat1, lon1, lat2, lon2) {
    const R    = 6371000;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a    = Math.sin(dLat/2)**2 +
                 Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) *
                 Math.sin(dLon/2)**2;
    return Math.round(6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)));
  },

  getLokasi() {
    return new Promise((resolve, reject) => {
      if (!navigator.geolocation) return reject(new Error('GPS tidak didukung'));
      navigator.geolocation.getCurrentPosition(
        p  => resolve({ lat: p.coords.latitude, lon: p.coords.longitude }),
        err => reject(new Error('GPS gagal: ' + err.message)),
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    });
  }
};

// ============================================
// HELPERS
// ============================================
export const Helper = {
  jamSekarang() {
    const now = new Date();
    const h = String(now.getHours()).padStart(2, '0');
    const m = String(now.getMinutes()).padStart(2, '0');
    return `${h}:${m}`;
  },
  tanggalHariIni() {
    return new Date().toLocaleDateString('id-ID', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
    });
  },
  tanggalISO() {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  },
  generateId(prefix) {
    return prefix + Date.now().toString(36).toUpperCase();
  },
  statusMasuk(jamMasuk, toleransi) {
    const now  = new Date();
    const [h, m] = jamMasuk.split(':').map(Number);
    const batas  = new Date();
    batas.setHours(h, m + toleransi, 0, 0);
    if (now <= batas) return { status: 'Tepat Waktu', menit: 0 };
    return { status: 'Terlambat', menit: Math.round((now - batas) / 60000) };
  },
  statusKeluar(jamKeluar) {
    const now  = new Date();
    const [h, m] = jamKeluar.split(':').map(Number);
    const batas  = new Date();
    batas.setHours(h, m, 0, 0);
    if (now >= batas) return { status: 'Tepat Waktu', menit: 0 };
    return { status: 'Pulang Cepat', menit: Math.round((batas - now) / 60000) };
  },
  simpanSession: (u) => localStorage.setItem('absensi_v2_user', JSON.stringify(u)),
  getSession   : ()  => { try { return JSON.parse(localStorage.getItem('absensi_v2_user')); } catch { return null; } },
  hapusSession : ()  => localStorage.removeItem('absensi_v2_user'),
};
